CREATE OR REPLACE FUNCTION public.finish_agent_job(p_id uuid,p_text text,p_metadata jsonb,p_waiting boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE j public.agent_jobs; BEGIN SELECT * INTO j FROM public.agent_jobs WHERE id=p_id AND status='running' FOR UPDATE; IF NOT FOUND THEN RETURN false; END IF; IF length(trim(p_text))=0 THEN RAISE EXCEPTION 'Empty task result'; END IF; INSERT INTO public.messages(id,user_id,conversation_id,bot_id,role,content,metadata) VALUES(j.id,j.user_id,j.conversation_id,j.bot_id,'assistant',p_text,p_metadata) ON CONFLICT(id) DO NOTHING; UPDATE public.agent_jobs SET status=CASE WHEN p_waiting THEN 'failed' ELSE 'completed' END,result=p_text,error=CASE WHEN p_waiting THEN 'Sign-in required; review and resume after login' ELSE NULL END WHERE id=j.id; UPDATE public.conversations SET updated_at=now() WHERE id=j.conversation_id AND user_id=j.user_id; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.finish_agent_job(uuid,text,jsonb,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finish_agent_job(uuid,text,jsonb,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.finish_routine_run(p_run uuid,p_text text,p_metadata jsonb,p_waiting boolean,p_next timestamptz) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE r public.agent_routine_runs; a public.agent_routines; BEGIN SELECT * INTO r FROM public.agent_routine_runs WHERE id=p_run AND status='running' FOR UPDATE; IF NOT FOUND THEN RETURN false; END IF; SELECT * INTO a FROM public.agent_routines WHERE id=r.routine_id AND user_id=r.user_id FOR UPDATE; IF NOT FOUND THEN RETURN false; END IF; IF length(trim(p_text))=0 THEN RAISE EXCEPTION 'Empty task result'; END IF; INSERT INTO public.messages(id,user_id,conversation_id,bot_id,role,content,metadata) SELECT r.id,r.user_id,a.conversation_id,c.bot_id,'assistant',a.title||E'\n\n'||p_text,p_metadata FROM public.conversations c WHERE c.id=a.conversation_id AND c.user_id=r.user_id ON CONFLICT(id) DO NOTHING; IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM public.messages WHERE id=r.id AND user_id=r.user_id) THEN RAISE EXCEPTION 'Conversation unavailable'; END IF; UPDATE public.agent_routine_runs SET status=CASE WHEN p_waiting THEN 'failed' ELSE 'completed' END,result=p_text,error=CASE WHEN p_waiting THEN 'Sign-in required; task not completed' ELSE NULL END WHERE id=r.id; UPDATE public.agent_routines SET next_run_at=p_next,active=active AND NOT p_waiting,lease_until=NULL,last_result=p_text,last_error=CASE WHEN p_waiting THEN 'Sign-in required; resume after login' ELSE NULL END WHERE id=a.id; UPDATE public.conversations SET updated_at=now() WHERE id=a.conversation_id AND user_id=r.user_id; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.finish_routine_run(uuid,text,jsonb,boolean,timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finish_routine_run(uuid,text,jsonb,boolean,timestamptz) TO service_role;